function parseScalar(s){
  s=String(s).trim();
  if(s===''||s==='null'||s==='~') return null;
  if(s==='true') return true; if(s==='false') return false;
  if(/^-?\d+$/.test(s)) return parseInt(s,10);
  if(/^-?\d+\.\d+$/.test(s)) return parseFloat(s);
  if((s[0]==='"'&&s[s.length-1]==='"')||(s[0]==="'"&&s[s.length-1]==="'")) return s.slice(1,-1);
  return s;
}
function parseYaml(text){
  var raw=String(text).split(/\r?\n/); var lines=[];
  for(var i=0;i<raw.length;i++){ var l=raw[i].replace(/\t/g,'  '); if(l.trim()===''||/^\s*#/.test(l)) continue; lines.push(l); }
  function ind(l){ return l.match(/^ */)[0].length; }
  function parse(lines, base){
    if(lines.length && /^\s*-(\s|$)/.test(lines[0])){
      var arr=[], i=0;
      while(i<lines.length){ var l=lines[i], d=ind(l); if(d<base) break;
        var content=l.slice(d+1).replace(/^-\s?/,'');
        if(content===''){ var sub=[], j=i+1; while(j<lines.length&&ind(lines[j])>d){sub.push(lines[j]);j++;} arr.push(parse(sub,d+1)); i=j; }
        else if(content.indexOf(':')>=0){ var item=[content], j=i+1; while(j<lines.length&&ind(lines[j])>d){item.push(lines[j].slice(d+1));j++;} arr.push(parse(item,0)); i=j; }
        else { arr.push(parseScalar(content)); i++; }
      }
      return arr;
    }
    var obj={}, i=0;
    while(i<lines.length){ var l=lines[i], d=ind(l); if(d<base) break;
      var mm=l.slice(d).match(/^([^:]+):\s?(.*)$/); if(!mm){i++;continue;}
      var key=mm[1].trim(), val=mm[2];
      if(val===''){ var sub=[], j=i+1; while(j<lines.length&&ind(lines[j])>d){sub.push(lines[j]);j++;} obj[key]= sub.length?parse(sub,d+1):null; i=j; }
      else { obj[key]=parseScalar(val); i++; }
    }
    return obj;
  }
  return parse(lines,0);
}
function emitYaml(v){
  function esc(s){ if(typeof s==='string'){ if(s===''||/[:#\n]/.test(s)||/^\s|\s$/.test(s)) return '"'+s+'"'; } return s; }
  function rec(v,d){
    if(Array.isArray(v)){ if(!v.length) return '[]'; return v.map(function(it){ return d+'- '+ (typeof it==='object'&&it!==null? '\n'+rec(it,d+'  ').replace(/^/gm,d+'  ') : esc(it)); }).join('\n'); }
    if(v!==null&&typeof v==='object'){ var ks=Object.keys(v); if(!ks.length) return '{}'; return ks.map(function(k){ var val=v[k]; if(val!==null&&typeof val==='object'){ return d+k+':\n'+rec(val,d+'  '); } return d+k+': '+esc(val); }).join('\n'); }
    return d+esc(v);
  }
  return rec(v,'');
}
